  public RemoteUi(){using(var s=Assembly.GetExecutingAssembly().GetManifestResourceStream("RemoteWindow.xaml"))Window=(Window)XamlReader.Load(s);Theme.Apply(Window,"System");using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("AstroArchive_Logo.png")){var image=new BitmapImage();image.BeginInit();image.StreamSource=stream;image.CacheOption=BitmapCacheOption.OnLoad;image.EndInit();image.Freeze();Find<Image>("BrandLogo").Source=image;Window.Icon=image;}Window.MinWidth=Math.Min(Window.MinWidth,SystemParameters.WorkArea.Width-24);Window.MinHeight=Math.Min(Window.MinHeight,SystemParameters.WorkArea.Height-24);Window.Width=Math.Min(Window.Width,SystemParameters.WorkArea.Width-24);Window.Height=Math.Min(Window.Height,SystemParameters.WorkArea.Height-24);
