   Button("DefaultsButton").Click+=(s,e)=>{if(Combo("NetworkBox").SelectedIndex!=0){SetStatus("Hotspot defaults apply only to the telescope hotspot. Find the current STA address in the telescope app or router.");return;}Box("HostBox").Text=Kind=="DWARF FTP"?"192.168.88.1":"10.0.0.1";Box("FolderBox").Text=Kind=="DWARF FTP"?"/":@"\\10.0.0.1\EMMC Images\MyWorks";};Button("WifiButton").Click+=(s,e)=>Open("ms-settings:network-wifi");Button("AddressesButton").Click+=(s,e)=>Addresses();Button("GuideButton").Click+=(s,e)=>Open(Kind=="DWARF FTP"?"https://help.dwarflab.com/en/docs/How-to-View-and-Edit-DWARF-3-Files-Wirelessly-on-Your-Computer":"https://www.seestar.com/blogs/tutorial/simulated-stargazing");Button("TestButton").Click+=async(s,e)=>await Probe();Button("ParentButton").Click+=async(s,e)=>{string f=Box("FolderBox").Text.TrimEnd('/','\\');Box("FolderBox").Text=Kind=="DWARF FTP"?(f.LastIndexOf('/')<=0?"/":f.Substring(0,f.LastIndexOf('/'))):(Path.GetDirectoryName(f)??f);await Probe();};Find<DataGrid>("FolderGrid").MouseDoubleClick+=async(s,e)=>{var row=Find<DataGrid>("FolderGrid").SelectedItem as FolderRow;if(row!=null&&row.Directory&&!busy){Box("FolderBox").Text=row.Path;await Probe();}};
   Box("HostBox").LostKeyboardFocus+=(s,e)=>{if(Kind=="Seestar SMB"){string path=Box("FolderBox").Text;int end=path.IndexOf('\\',2);if(path.StartsWith(@"\\")&&end>2)Box("FolderBox").Text=@"\\"+Box("HostBox").Text.Trim()+path.Substring(end);}};Box("FolderBox").LostKeyboardFocus+=(s,e)=>{if(Kind=="Seestar SMB"){string path=Box("FolderBox").Text;int end=path.IndexOf('\\',2);if(path.StartsWith(@"\\")&&end>2)Box("HostBox").Text=path.Substring(2,end-2);}};Button("SourceBrowseButton").Click+=(s,e)=>{Pick("FolderBox");if(Kind=="Seestar SMB"){string path=Box("FolderBox").Text;int end=path.IndexOf('\\',2);if(path.StartsWith(@"\\")&&end>2)Box("HostBox").Text=path.Substring(2,end-2);}};Button("DestinationBrowseButton").Click+=(s,e)=>Pick("DestinationBox");Button("OpenButton").Click+=(s,e)=>{string path=Box("DestinationBox").Text;if(Directory.Exists(path))Open(path);else SetStatus("Start a download or choose an existing local folder first.");};Button("StartButton").Click+=(s,e)=>Start();Button("StopButton").Click+=(s,e)=>Stop();Button("VerifyButton").Click+=async(s,e)=>await Verify();Button("ReportButton").Click+=(s,e)=>Export();Button("SimulatorButton").Click+=async(s,e)=>await Simulate();
   timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(400)};timer.Tick+=(s,e)=>Tick();timer.Start();Window.Closing+=(s,e)=>{closing=true;if(discoveryCancel!=null)discoveryCancel.Cancel();Stop();if(simulatorCancel!=null)simulatorCancel.Cancel();timer.Stop();};
