  string Kind{get{return Convert.ToString(Combo("KindBox").SelectedItem);}}
  void Guide(){bool ftp=Kind=="DWARF FTP",sim=Kind=="Local simulator",hotspot=Combo("NetworkBox").SelectedIndex==0;Find<Grid>("FtpCredentials").Visibility=ftp?Visibility.Visible:Visibility.Collapsed;Box("HostBox").IsEnabled=!sim;Button("SourceBrowseButton").Visibility=ftp?Visibility.Collapsed:Visibility.Visible;Button("DefaultsButton").Visibility=sim?Visibility.Collapsed:Visibility.Visible;Button("GuideButton").Visibility=sim?Visibility.Collapsed:Visibility.Visible;Combo("NetworkBox").IsEnabled=!sim;Find<StackPanel>("DiscoveryPanel").Visibility=sim?Visibility.Collapsed:Visibility.Visible;Button("DiscoverButton").IsEnabled=!busy&&Combo("DiscoveryNetworkBox").SelectedItem!=null;Button("UseDiscoveryButton").IsEnabled=!busy&&Find<DataGrid>("DiscoveryGrid").SelectedItem is DiscoveredTelescope;
   Label("SetupGuide").Text=sim?"Use a local folder as the source. The built-in simulator creates unique, slowly written FITS exposures for this tester. Choose a separate destination.":ftp?(hotspot?"Power on DWARF 3 or mini and tap Connect in the DWARFLAB app to enable its Wi-Fi. On this PC, open Wi-Fi settings and join the DWARF hotspot. Use the Wi-Fi password shown in the app; the documented DWARF 3 default is DWARF_12345678. Keep shooting in the phone app.":"In the DWARFLAB app, connect the telescope to your home Wi-Fi using STA mode. Connect this PC to the same LAN. Verify FTP access on your model and firmware; hotspot defaults do not apply on the home LAN."):(hotspot?"Power on Seestar. Connect your phone through the Seestar app, then join the Seestar hotspot from this PC. Use the Wi-Fi password shown in the app; the documented default is 12345678. Enable Save Each Frame in Seestar's capture settings.":"In Seestar settings, open Wi-Fi → STA Mode and join your home Wi-Fi. Reconnect the app, and connect this PC to the same LAN. Enable Save Each Frame so individual exposures are stored.");
   Label("IpGuide").Text=sim?"No IP address is needed. Browse to a local source folder or use Start local simulator.":hotspot?(ftp?"The documented DWARF hotspot address is 192.168.88.1. Choose Use hotspot defaults, then test FTP access. This tester defaults to anonymous FTP; use different credentials only if your device instructions specify them. DWARF II support must be checked on its firmware.":"The documented Seestar hotspot address is 10.0.0.1. Choose Use hotspot defaults. In File Explorer, open \\"+"10.0.0.1 and inspect the shares. The documented share is EMMC Images; its capture folder is MyWorks. Use the names your device actually exposes."):(ftp?"Find the DWARF address in its app's connection/STA information if displayed. Otherwise open your router's connected-device list and identify the DWARF by its device name or MAC address. Enter that IPv4 address here. Do not use this PC's IPv4 address.":"In the Seestar app, open device settings → Wi-Fi → STA Mode → the connected network's information icon. Copy its IP address. Alternatively identify Seestar in your router's connected-device list. Enter that IP below and replace the IP in the source folder too.");if(!sim)Label("IpGuide").Text="Choose Find telescopes below to discover devices on this network. Select yours and choose Use selected telescope.\n\n"+Label("IpGuide").Text;Label("FolderHint").Text=ftp?"Start with /, test the connection, then enter Astronomy and the desired DWARF_RAW session. Folder names may vary by firmware.":sim?"Select a source folder that is separate from the download folder.":@"Open \\<telescope-IP>\ in File Explorer to confirm the share, then paste its full path here. Authenticate in Windows if prompted.";
