  void RefreshNetworks(){try{var previous=Combo("DiscoveryNetworkBox").SelectedItem as DiscoveryNetwork;var networks=DiscoveryNetwork.Available();Combo("DiscoveryNetworkBox").ItemsSource=networks;Combo("DiscoveryNetworkBox").SelectedItem=previous==null?networks.FirstOrDefault():networks.FirstOrDefault(n=>n.Address==previous.Address)??networks.FirstOrDefault();Label("DiscoveryStatus").Text=networks.Count==0?"No active Wi-Fi or Ethernet IPv4 network. Connect this PC, then Refresh networks.":"Choose the network shared with the telescope, then Find telescopes (about 8 seconds).";Button("DiscoverButton").IsEnabled=!busy&&networks.Count>0;}catch(Exception e){Label("DiscoveryStatus").Text="Could not read network connections: "+e.Message;Button("DiscoverButton").IsEnabled=false;}}
  async Task Discover(){if(busy)return;var network=Combo("DiscoveryNetworkBox").SelectedItem as DiscoveryNetwork;if(network==null){RefreshNetworks();return;}Find<DataGrid>("DiscoveryGrid").ItemsSource=null;var cancel=new CancellationTokenSource();discoveryCancel=cancel;SetBusy(true,false);Button("CancelDiscoveryButton").Visibility=Visibility.Visible;Label("DiscoveryStatus").Text="Searching "+network.Display+"…";SetStatus("Discovering DWARF and Seestar devices. Capture continues in the telescope app.");try{var result=await Task.Run(()=>TelescopeDiscovery.Find(network,cancel.Token));if(closing)return;Find<DataGrid>("DiscoveryGrid").ItemsSource=result.Devices.OrderBy(d=>d.Name).ThenBy(d=>d.Host).ToList();foreach(string warning in result.Warnings)Log(warning);string message=result.Devices.Count==0?"No telescope replies. Confirm the same subnet, the telescope is awake and guest/client isolation is off. Check Windows firewall permission for this app on your trusted private network, or enter the IP manually.":result.Devices.Count+" telescope(s) found. Select yours, then Use selected telescope and Test connection / list.";if(result.Warnings.Count>0)message+=" "+string.Join(" ",result.Warnings);Label("DiscoveryStatus").Text=message;SetStatus(result.Devices.Count==0?"Discovery finished without a telescope reply. See the network guidance above.":"Discovery complete. Select a telescope to fill in its address.");Log("Discovery on "+network.Display+": "+result.Devices.Count+" device(s). File access has not yet been tested.");}catch(OperationCanceledException){if(!closing){Label("DiscoveryStatus").Text="Search cancelled. You can search again or enter the IP manually.";SetStatus("Discovery cancelled.");}}catch(Exception e){if(!closing){Label("DiscoveryStatus").Text="Discovery failed: "+e.Message;Log("Discovery: "+e.Message);SetStatus("Discovery failed. You can still enter the telescope IP manually.");}}finally{discoveryCancel=null;cancel.Dispose();if(!closing){Button("CancelDiscoveryButton").Visibility=Visibility.Collapsed;SetBusy(false,false);}}}
  void UseDiscovered(){if(busy)return;var device=Find<DataGrid>("DiscoveryGrid").SelectedItem as DiscoveredTelescope;if(device==null)return;string oldKind=Kind,folder=Box("FolderBox").Text;Combo("KindBox").SelectedItem=device.Kind;Box("HostBox").Text=device.Host;if(device.Kind=="Seestar SMB"){int end=folder.IndexOf('\\',2);Box("FolderBox").Text=oldKind==device.Kind&&folder.StartsWith(@"\\")&&end>2?@"\\"+device.Host+folder.Substring(end):@"\\"+device.Host+@"\EMMC Images\MyWorks";}else Box("FolderBox").Text=oldKind==device.Kind&&folder.StartsWith("/")?folder:"/";Find<DataGrid>("FolderGrid").ItemsSource=null;SetStatus("Selected "+device.Name+" at "+device.Host+". Test connection / list to check file access; discovery does not verify SMB credentials or FTP availability.");Log("Selected discovered "+device.Name+" · "+device.Host);}
  public void CheckDiscoverySelection(){var original=Read();var grid=Find<DataGrid>("DiscoveryGrid");Combo("KindBox").SelectedItem="Seestar SMB";Box("FolderBox").Text=@"\\10.0.0.1\EMMC Images\MyWorks\session";var device=new DiscoveredTelescope{Kind="Seestar SMB",Name="Seestar test",Host="192.168.1.42"};grid.ItemsSource=new[]{device};grid.SelectedItem=device;UseDiscovered();if(Box("HostBox").Text!=device.Host||Box("FolderBox").Text!=@"\\192.168.1.42\EMMC Images\MyWorks\session")throw new InvalidOperationException("Discovery did not preserve the selected SMB folder.");device=new DiscoveredTelescope{Kind="DWARF FTP",Name="DWARF test",Host="192.168.1.43"};grid.ItemsSource=new[]{device};grid.SelectedItem=device;UseDiscovered();if(Kind!=device.Kind||Box("HostBox").Text!=device.Host||Box("FolderBox").Text!="/")throw new InvalidOperationException("Discovery did not switch telescope connection type.");grid.ItemsSource=null;Apply(original);Guide();Box("ActivityBox").Clear();SetStatus("Choose a connection type, follow the setup guide, then test the connection.");}
  async Task CheckSmb(){Button("SmbHelpButton").IsEnabled=false;Label("SmbStatus").Visibility=Visibility.Visible;Label("SmbStatus").Text="Reading Windows SMB client settings…";try{string text=await Task.Run(()=>{using(var process=Process.Start(new ProcessStartInfo{FileName=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),@"WindowsPowerShell\v1.0\powershell.exe"),Arguments="-NoProfile -NonInteractive -Command \"Get-SmbClientConfiguration -ErrorAction Stop | Select-Object EnableInsecureGuestLogons,RequireSecuritySignature | Format-List\"",UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true})){if(!process.WaitForExit(10000)){process.Kill();throw new IOException("Reading SMB settings timed out.");}string output=process.StandardOutput.ReadToEnd(),error=process.StandardError.ReadToEnd();if(process.ExitCode!=0)throw new IOException(error.Trim());return output.Trim();}});if(closing)return;Label("SmbStatus").Text=text+"\n\nThese are read-only results. EnableInsecureGuestLogons=False or RequireSecuritySignature=True can prevent access to a guest-only Seestar share. Clear only stale credentials for this telescope in Windows Credential Manager, then retry in File Explorer. If it still fails, compare these settings with Seestar login help. Discovery cannot bypass SMB authentication or signing.";Log("SMB client settings (read only): "+text);}catch(Exception e){if(!closing)Label("SmbStatus").Text="Could not read SMB settings: "+e.Message+"\nIn PowerShell run: Get-SmbClientConfiguration | Select-Object EnableInsecureGuestLogons, RequireSecuritySignature";}finally{if(!closing)Button("SmbHelpButton").IsEnabled=true;}}
  void Addresses(){var lines=new List<string>{"These are this PC's addresses. Use Find telescopes to discover the telescope."};foreach(var adapter in NetworkInterface.GetAllNetworkInterfaces().Where(a=>a.OperationalStatus==OperationalStatus.Up&&a.NetworkInterfaceType!=NetworkInterfaceType.Loopback)){var properties=adapter.GetIPProperties();foreach(var address in properties.UnicastAddresses.Where(a=>a.Address.AddressFamily==System.Net.Sockets.AddressFamily.InterNetwork))lines.Add(adapter.Name+": PC "+address.Address+" · mask "+address.IPv4Mask);foreach(var gateway in properties.GatewayAddresses)lines.Add("Gateway / router: "+gateway.Address);}lines.Add("On a home LAN, the gateway is usually your router. Its connected-device list can show the telescope IP. On a telescope hotspot, the gateway may be the telescope; confirm by testing file access.");Label("AddressesText").Text=string.Join(Environment.NewLine,lines);Label("AddressesText").Visibility=Visibility.Visible;}
  Connection Read(){int port,poll;if(!int.TryParse(Box("PortBox").Text,out port)||!int.TryParse(Box("PollBox").Text,out poll))throw new ArgumentException("Enter whole numbers for FTP port and poll interval.");string limit=Convert.ToString(Combo("LimitBox").SelectedItem);return new Connection{Kind=Kind,Host=Box("HostBox").Text.Trim(),Folder=Box("FolderBox").Text.Trim(),Destination=Box("DestinationBox").Text.Trim(),User=Box("UserBox").Text.Trim(),Password=Find<PasswordBox>("PasswordBox").Password,Port=port,PollSeconds=poll,LimitMB=limit=="Unlimited"?0:double.Parse(limit.Split(' ')[0],CultureInfo.InvariantCulture),IncludeExisting=Find<CheckBox>("ExistingCheck").IsChecked==true};}
  void Apply(Connection c){Combo("KindBox").SelectedItem=c.Kind;Box("HostBox").Text=c.Host;Box("FolderBox").Text=c.Folder;Box("DestinationBox").Text=c.Destination;Box("UserBox").Text=c.User;Box("PortBox").Text=c.Port.ToString();Box("PollBox").Text=c.PollSeconds.ToString();Combo("LimitBox").SelectedItem=c.LimitMB==0?"Unlimited":c.LimitMB.ToString(CultureInfo.InvariantCulture)+" MB/s";Find<CheckBox>("ExistingCheck").IsChecked=c.IncludeExisting;}
  void Save(Connection c){var safe=new Connection{Kind=c.Kind,Host=c.Host,Folder=c.Folder,Destination=c.Destination,User=c.User,Port=c.Port,PollSeconds=c.PollSeconds,LimitMB=c.LimitMB,IncludeExisting=c.IncludeExisting};Json.Save(Path.Combine(state,"settings.json"),safe);}
  Process Launch(Connection c,string mode,out string path){path=Path.Combine(state,"runs",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(path);string config=Path.Combine(path,"connection.json");Json.Save(config,c);File.WriteAllText(Path.Combine(path,"mode"),mode);return Process.Start(new ProcessStartInfo{FileName=Assembly.GetExecutingAssembly().Location,Arguments="--worker \""+config+"\" \""+path+"\"",UseShellExecute=false,CreateNoWindow=true});}
  async Task Probe(){if(busy)return;Process process=null;string path=null;SetBusy(true,false);try{var c=Read();c.Validate(false);SetStatus("Testing file access and listing the selected folder…");process=Launch(c,"list",out path);await Task.Run(()=>{if(!process.WaitForExit(30000)){process.Kill();process.WaitForExit();throw new IOException("File access timed out. Check the network, telescope IP and selected folder.");}});var result=Json.Read<ProbeResult>(Path.Combine(path,"result.json"));if(!result.Success)throw new IOException(result.Error+" (0x"+result.ErrorCode.ToString("X8")+")");Find<DataGrid>("FolderGrid").ItemsSource=result.Entries.OrderByDescending(e=>e.Directory).ThenBy(e=>e.Name).Select(e=>new FolderRow{Name=e.Name,Path=e.Path,Directory=e.Directory,Type=e.Directory?"Folder":"File"}).ToList();Save(c);SetStatus("Connected. "+result.Entries.Count+" entries in the selected folder. Choose the capture session, then Start watching.");Log("File access succeeded: "+c.Folder);}catch(Exception e){SetStatus(e.Message);Log("Connection test: "+e.Message);if(!closing&&Kind=="Seestar SMB"){Label("SmbStatus").Visibility=Visibility.Visible;Label("SmbStatus").Text="Windows SMB returned: "+e.Message+"\nOpen the same source folder in File Explorer to test Windows access. If credentials are rejected, choose Check SMB access. Discovery finds the IP but cannot fix guest-access or signing restrictions.";}}finally{if(process!=null)process.Dispose();DeleteConfig(path);if(!closing)SetBusy(false,false);}}
  void Start(){if(busy)return;try{var c=Read();c.Validate(true);Save(c);rows.Clear();indexed.Clear();eventOffset=0;active=c;worker=Launch(c,"watch",out work);SetBusy(true,true);SetStatus("Watching selected folder. New files wait for stable listings before downloading.");Log("Watching "+c.Kind+" "+c.Folder+" → "+c.Destination);}catch(Exception e){SetStatus(e.Message);}}
  void Stop(){if(worker!=null){try{if(!worker.HasExited){worker.Kill();worker.WaitForExit(2000);}ReadEvents();}catch(Exception e){Log("Stop: "+e.Message);}finally{worker.Dispose();worker=null;DeleteConfig(work);SetBusy(false,false);}SetStatus("Stopped. Completed downloads are retained. Start watching to catch up.");}}
  async Task Verify(){if(busy)return;Process process=null;string path=null;SetBusy(true,false);try{var c=Read();c.Validate(true);process=Launch(c,"verify",out path);SetStatus("Checking downloaded FITS files against their saved local hashes…");await Task.Run(()=>{if(!process.WaitForExit(120000)){process.Kill();process.WaitForExit();throw new IOException("Verification timed out. Choose a smaller test destination.");}});if(File.Exists(Path.Combine(path,"result.json"))){var result=Json.Read<ProbeResult>(Path.Combine(path,"result.json"));if(!result.Success)throw new IOException(result.Error);}if(File.Exists(Path.Combine(path,"events.jsonl")))foreach(string line in File.ReadAllLines(Path.Combine(path,"events.jsonl")))Consume(new JavaScriptSerializer().Deserialize<Notice>(line));SetStatus("Verification finished. Review Verified / Failed rows.");}catch(Exception e){SetStatus(e.Message);}finally{if(process!=null)process.Dispose();DeleteConfig(path);if(!closing)SetBusy(false,false);}}
  void Tick(){if(worker==null)return;ReadEvents();if(worker.HasExited){try{string result=Path.Combine(work,"result.json");SetStatus(File.Exists(result)?Json.Read<ProbeResult>(result).Error:"Download worker stopped.");}catch{SetStatus("Download worker stopped; export the report for diagnosis.");}worker.Dispose();worker=null;DeleteConfig(work);SetBusy(false,false);}}
  void ReadEvents(){try{string path=Path.Combine(work,"events.jsonl");if(!File.Exists(path))return;using(var f=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite)){f.Position=eventOffset;using(var reader=new StreamReader(f,Encoding.UTF8)){string tail=reader.ReadToEnd();int last=tail.LastIndexOf('\n');if(last<0)return;string complete=tail.Substring(0,last+1);eventOffset+=Encoding.UTF8.GetByteCount(complete);foreach(string line in complete.Split(new[]{'\n'},StringSplitOptions.RemoveEmptyEntries))Consume(new JavaScriptSerializer().Deserialize<Notice>(line));}}}catch(IOException){}catch(Exception e){Log("Report read: "+e.Message);}}
  void Consume(Notice n){if(notices.Count>=10000)notices.RemoveAt(0);notices.Add(n);if(!string.IsNullOrEmpty(n.File)){FileRow row;if(!indexed.TryGetValue(n.File,out row)){row=new FileRow{File=n.File};indexed[n.File]=row;rows.Add(row);}bool changed=row.State!=n.State||row.Message!=n.Message;row.State=n.State;row.Size=n.Bytes>0?(n.Bytes/1048576.0).ToString("0.00")+" MB":"";row.Message=n.Message;if(changed)Log(n.File+": "+n.State+" · "+n.Message);Find<DataGrid>("FilesGrid").Items.Refresh();}else{SetStatus(n.Message);Log(n.Message);}Label("SummaryText").Text=rows.Count(r=>r.State=="Downloaded"||r.State=="Verified")+" downloaded · "+rows.Count(r=>r.State=="Waiting")+" waiting · "+rows.Count(r=>r.State=="Retry"||r.State=="Failed")+" need attention";}
  void SetBusy(bool value,bool watching){busy=value;foreach(string n in new[]{"KindBox","NetworkBox","HostBox","PortBox","UserBox","PasswordBox","FolderBox","DestinationBox","ExistingCheck","PollBox","LimitBox","TestButton","ParentButton","SourceBrowseButton","DestinationBrowseButton","DefaultsButton","StartButton","VerifyButton","SimulatorButton","DiscoverButton","RefreshNetworksButton","DiscoveryNetworkBox","DiscoveryGrid","UseDiscoveryButton"})Find<Control>(n).IsEnabled=!value;Button("StopButton").IsEnabled=watching;if(!value){Guide();Button("SimulatorButton").IsEnabled=!simulating;}}
  void SetStatus(string text){Label("StatusText").Text=text;}
  void Log(string text){var box=Box("ActivityBox");if(box.Text.Length>50000)box.Text=box.Text.Substring(box.Text.Length-25000);box.AppendText(DateTime.Now.ToString("HH:mm:ss")+"  "+text+Environment.NewLine);box.ScrollToEnd();}
  static void DeleteConfig(string path){try{if(path!=null)File.Delete(Path.Combine(path,"connection.json"));}catch{}}
  void Pick(string box){using(var dialog=new System.Windows.Forms.FolderBrowserDialog{Description=box=="DestinationBox"?"Choose a dedicated local download folder":"Choose the telescope network folder or local simulator source",SelectedPath=Box(box).Text,ShowNewFolderButton=box=="DestinationBox"})if(dialog.ShowDialog()==System.Windows.Forms.DialogResult.OK)Box(box).Text=dialog.SelectedPath;}
  void Open(string path){try{Process.Start(new ProcessStartInfo(path){UseShellExecute=true});}catch(Exception e){SetStatus(e.Message);}}
  void Export(){var picker=new SaveFileDialog{Title="Save Remote tester report",FileName="AstroArchive-Remote-Test-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".json",Filter="JSON report|*.json"};if(picker.ShowDialog(Window)!=true)return;try{var c=active??Read();File.WriteAllText(picker.FileName,Json.Serialize(new{Application="AstroArchive Remote tester 0.1.2",Generated=DateTimeOffset.Now.ToString("o"),Connection=new{c.Kind,c.Host,c.Port,c.Folder,c.Destination,c.PollSeconds,c.LimitMB,c.IncludeExisting},Events=notices,Activity=Box("ActivityBox").Text,Limitations="FITS structure and local hashes only; no independent source checksums. Individual FITS exposures; no session sidecars."}),new UTF8Encoding(false));SetStatus("Report saved. It includes network addresses and file paths, but no passwords.");}catch(Exception e){SetStatus(e.Message);}}
  async Task Simulate(){if(busy||simulating)return;simulating=true;simulatorCancel=new CancellationTokenSource();var cancel=simulatorCancel;string folder=Path.Combine(state,"Simulator",DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,6));Combo("KindBox").SelectedItem="Local simulator";Box("FolderBox").Text=folder;Directory.CreateDirectory(folder);Log("Simulator source: "+folder);SetStatus("Simulator running. Click Start watching to download its arriving exposures.");Button("SimulatorButton").IsEnabled=false;try{await Task.Run(()=>{for(int i=1;i<=12;i++){cancel.Token.ThrowIfCancellationRequested();Program.WriteSample(Path.Combine(folder,"DWARF_RAW_TEST","raw_"+i.ToString("0000")+".fits"),i,true);if(cancel.Token.WaitHandle.WaitOne(1500))cancel.Token.ThrowIfCancellationRequested();}});if(!closing)Log("Simulator finished: 12 unique FITS exposures.");}catch(OperationCanceledException){}catch(Exception e){if(!closing)Log("Simulator: "+e.Message);}finally{simulating=false;cancel.Dispose();simulatorCancel=null;if(!closing)Button("SimulatorButton").IsEnabled=!busy;}}
 }
}
